function renderOnlineCart(){const list=document.getElementById('onlineCartItems'),totalNode=document.getElementById('onlineCartTotal');if(!list)return;let total=0;list.innerHTML=onlineCart.length?onlineCart.map((item,index)=>{const product=findProduct(item.name),price=moneyNumber(product?.[2]||item.price);total+=price*item.quantity;return `<div class="online-cart-row"><div><strong>${escapeHTML(item.name)}</strong><small>${dashboardMoney(price)} each Â· ${escapeHTML(String(product?.[3]??0))} available</small></div><div class="online-quantity"><button type="button" data-online-step="-1" data-online-index="${index}" aria-label="Decrease ${escapeHTML(item.name)} quantity">&#8722;</button><span>${item.quantity}</span><button type="button" data-online-step="1" data-online-index="${index}" aria-label="Increase ${escapeHTML(item.name)} quantity">+</button><button type="button" class="online-remove" data-online-remove="${index}" aria-label="Remove ${escapeHTML(item.name)}">&times;</button></div><strong>${dashboardMoney(price*item.quantity)}</strong></div>`}).join(''):'<p class="online-cart-empty">Your cart is empty. Add products from the catalog above.</p>';totalNode.textContent=dashboardMoney(total);document.getElementById('placeOnlineOrder').disabled=!onlineCart.length}
document.getElementById('tableBody').addEventListener('click',e=>{const button=e.target.closest('[data-online-add]');if(!button)return;const name=button.closest('tr').cells[0].innerText.trim(),product=findProduct(name);if(!product){toast('Product is no longer available.');return}const stock=Math.max(0,Math.floor(Number(product[3])||0)),existing=onlineCart.find(item=>item.name.toLowerCase()===name.toLowerCase());if(stock<=0||(existing?.quantity||0)>=stock){toast(stock?'Cart quantity cannot exceed available stock.':'This product is out of stock.');return}if(existing)existing.quantity++;else onlineCart.push({name,price:product[2],quantity:1});renderOnlineCart();onlineOrderPanel.scrollIntoView({behavior:'smooth',block:'nearest'})});
onlineOrderPanel.addEventListener('click',e=>{const remove=e.target.closest('[data-online-remove]');if(remove){onlineCart.splice(Number(remove.dataset.onlineRemove),1);renderOnlineCart();return}const step=e.target.closest('[data-online-step]');if(step){const index=Number(step.dataset.onlineIndex),item=onlineCart[index],product=item&&findProduct(item.name);if(!item||!product)return;const next=item.quantity+Number(step.dataset.onlineStep),stock=Math.max(0,Math.floor(Number(product[3])||0));if(next<1)onlineCart.splice(index,1);else if(next>stock){toast('Cart quantity cannot exceed available stock.');return}else item.quantity=next;renderOnlineCart()}});
document.getElementById('onlineOrderForm').addEventListener('submit',e=>{e.preventDefault();if(!onlineCart.length)return;const form=e.currentTarget;if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form)),products=onlineCart.map(item=>findProduct(item.name));if(products.some((product,index)=>!product||Number(product[3])<onlineCart[index].quantity)){toast('Stock changed. Please review your cart.');renderOnlineCart();return}const before=structuredClone(rows),now=new Date(),date=now.toLocaleDateString(undefined,{month:'short',day:'2-digit'}),time=now.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}),money=value=>new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'}).format(value),total=onlineCart.reduce((sum,item,index)=>sum+moneyNumber(products[index][2])*item.quantity,0),customer=data.name.trim(),email=data.email.trim().toLowerCase(),items=onlineCart.map(item=>({name:item.name,quantity:item.quantity}));onlineCart.forEach((item,index)=>{const product=products[index],stock=Number(product[3])-item.quantity;product[3]=String(stock);product[4]=stock<=0?'Out of stock':stock<8?'Low stock':'Active';const inventory=rows.Inventory.find(row=>String(row[1]).trim().toLowerCase()===item.name.toLowerCase());if(inventory){inventory[2]=String(stock);inventory[4]=product[4]}});rows.Sales.unshift([`#WEB-${Date.now().toString().slice(-6)}`,customer,`${date}, ${time}`,money(total),'Pending',JSON.stringify(items),data.address.trim()]);const existing=rows.Customers.find(row=>String(row[1]).trim().toLowerCase()===email);if(existing)existing[2]=String((Number(existing[2])||0)+1);else rows.Customers.unshift([customer,email,'1','$0.00','Active']);if(!persistRows()){rows=before;toast('Could not save the order. Please try again.');return}onlineCart=[];form.reset();renderOnlineCart();renderModule('Online Store');renderDashboardData();toast('Order submitted. It is listed as Pending in Sales.')});const side=document.getElementById('sidebar'),shade=document.getElementById('shade');function closeMenu(){side.classList.remove('open');shade.classList.remove('show')}document.getElementById('menuBtn').addEventListener('click',()=>{side.classList.add('open');shade.classList.add('show')});shade.addEventListener('click',closeMenu);

const themeToggle=document.getElementById('themeToggle');
function setTheme(theme){document.documentElement.dataset.theme=theme;const light=theme==='light';themeToggle.innerHTML=light?'&#9790;':'&#9728;';themeToggle.setAttribute('aria-label',`Switch to ${light?'dark':'light'} mode`);themeToggle.title=`Switch to ${light?'dark':'light'} mode`;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',light?'#f3f6fb':'#0b1120')}
let savedTheme;try{savedTheme=localStorage.getItem('bizpilot-theme')}catch{}setTheme(savedTheme==='light'?'light':'dark');
themeToggle.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='light'?'dark':'light';setTheme(next);try{localStorage.setItem('bizpilot-theme',next)}catch{}});